// === Tab: mySketch ===
let zoom = 20;
let thick = 6;
let particles = [];
let set = false;

function equation(x, y) {
  let X = x * sin(y);
  let Y = y * cos(x);

  return createVector(X, Y);
}

class Particle {
	constructor(x, y) {
		this.x = x;
    this.y = y;
    this.vel = equation(x / zoom, y / zoom);
    this.life = 255;
    this.magnitude = this.vel.mag();
	}

  update() {
    let dir = equation(this.x / zoom, this.y / zoom);
    dir.normalize();

    this.vel = dir.copy().mult(this.magnitude);

		let lerpAmount = 0.1/30 * frameRate()

    this.x = lerp(this.x, this.x + this.vel.x, lerpAmount);
    this.y = lerp(this.y, this.y + this.vel.y, lerpAmount);

    this.life -= 1;

    this.magnitude = this.vel.mag();

    let magNorm = map(this.magnitude, 0, 10, 0, 1);

    let saturation = map(magNorm, 0, 1, 100, 255); 

    let hue = map(magNorm, 0, 1, 0, 255);
    let brightness = 255;

    let c = color(hue, saturation, brightness, this.life);
    fill(c);
  }

  show() {
    noStroke();
    ellipse(this.x, this.y, thick, thick);
  }

  isDead() {
    return this.life <= 0;
  }
}


function setup() {
  createCanvas(1000, 1000);
  colorMode(HSB, 255);
  background(0);
}

function draw() {
  translate(width/2, height/2);

  fill(0, 9);
  rect(-width/2, -height/2, width, height);

  let px = random(-width/2, width/2);
  let py = random(-height/2, height/2);

  particles.push(new Particle(px, py));

  for (let i = particles.length - 1; i >= 0; i--) {
    let p = particles[i];
    p.update();
    p.show();

    if (p.isDead()) {
      particles.splice(i, 1);
    }
  }

	if (set) {
		textSize(24);
		textAlign(LEFT, TOP);
		fill(255);
		rect(-width/2, -height/2, 220, 120);

		fill(0);
		text("Particle Count: " + particles.length, -width/2 + 10, -height/2 + 10);
		text("Zoom: " + zoom, -width/2 + 10, -height/2 + 34);
		text("Thickness: " + round(thick), -width/2 + 10, -height/2 + 58);
		text("frame rate: " + round(frameRate()), -width/2 + 10, -height/2 + 82);
	}

	if (keyIsPressed) {
		if (keyCode === UP_ARROW) {
			zoom += 0.5;
		}
		if (keyCode === DOWN_ARROW && zoom > 1) {
			zoom -= 0.5;
		}
		if (keyCode === RIGHT_ARROW) {
			thick += 0.1;
		}
		if (keyCode === LEFT_ARROW && thick > 1) {
			thick -= 0.1;
		}
	}
}

function keyPressed() {
	if (key == 's'){
		set = !set;
	}
}

